pm.test("Estado HTTP 200 OK", function () {
    pm.response.to.have.status(200);
});

const datos = pm.response.json();

pm.test("Receta vegetariana", function () {
    pm.expect(datos.vegetariano).to.eql(true);
});

pm.test("Receta sin gluten", function () {
    pm.expect(datos.sinGluten).to.eql(true);
});

pm.test("Receta rápida", function () {
    pm.expect(datos.rapido).to.eql(true);
});

pm.test("Receta económica", function () {
    pm.expect(datos.economico).to.eql(true);
});

pm.test("Coste por ración correcto", function () {
    pm.expect(Number(datos.costePorRacion)).to.eql(0.56);
});

pm.test("Contiene ingredientes", function () {
    pm.expect(datos.ingredientes.length).to.be.above(0);
});

pm.test("Contiene pasos ordenados", function () {
    const numeros = datos.pasos.map(paso => paso.numero);

    pm.expect(numeros).to.have.length.above(0);

    numeros.forEach((numero, indice) => {
        pm.expect(numero).to.eql(indice + 1);
    });
});

